entries[393974] = { ["name"] = "Versengender Schuss", ["text"] = "35 Meter Reichweite\nSofort\nFeuert eine Raketensalve ab, die Eurem aktuellen Ziel 52 Feuerschaden sowie zusätzlich Gegnern in der Nähe des Zielorts 6 Feuerschaden zufügt und Euch von den Füßen reißt." }
entries[393977] = { ["name"] = "Flüchtige Sande", ["text"] = "Sofort\nEin Hauch Zeitmagie, um Euch in Schwung zu bringen!\n\nErhöht die Bewegungsgeschwindigkeit 5 Sek. lang um 250%." }
