entries[393979] = { ["name"] = "Quecksilbersande", ["text"] = "Sofort\nDie Sande lassen Euch Zeit borgen, aber fordern sie später zurück.\n\nBewegungsgeschwindigkeit 10 Sek. lang um 200% erhöht, aber danach 10 Sek. lang um 90% verringert." }
