entries[393983] = { ["name"] = "Schnelligkeit des Horizontschreiters", ["text"] = "Kritischer Schaden und kritische Heilungen haben eine Chance, Euch anzuspornen und so Euer Tempo 10 Sek. lang um zu erhöhen. Dieser Effekt ist bis zu 5-mal stapelbar." }
