entries[393985] = { ["name"] = "Schwingende Sande", ["text"] = "Sofort\nDiese Sande verleihen Eurem Körper den Schwung, nach dem er sich sehnt!\n\nWerdet 10 Min. lang zum tanzenden Teufel!" }
entries[393987] = { ["name"] = "Azurgewobene Gewänder", ["text"] = "Ca. 4 Procs pro Minute\nDas Verursachen von Schaden hat eine Chance, Euch 'Azurgewobenes Durchdringen' zu gewähren, was Eure Intelligenz 8 Sek. lang erhöht. Heilung hat eine Chance, Euch 'Azurgewobenes Fließen' zu gewähren, was 8 Sek. lang die Manakosten von Zaubern verringert." }
entries[393988] = { ["name"] = "Tee der Fülle", ["text"] = "Sofort 30 sek. Abklingzeit\n'Donnerfokustee' stärkt auch zufällig 2 zusätzliche Einsätze von 'Einhüllender Nebel', 'Schadensumleitung' oder 'Tritt der aufgehenden Sonne'." }
entries[393989] = { ["name"] = "Zeitgefangene Sande", ["text"] = "Sofort\nWendet die Sicherheitsmaßnahmen des temporalen Konflux auf Euch selbst an!\n\nIhr seid 5 Min. lang in einer Blase gefangen." }
entries[393991] = { ["name"] = "Elunes Führung", ["text"] = "Inkarnation: Erwählter der Elune\nVerringert die für 'Sternensog' benötigte Astrale Macht um 10 und die für 'Sternenregen' benötigte Astrale Macht um 12.\n\nKonvokation der Geister\nVerringert die Abklingzeit um 50% und die Dauer sowie Anzahl der eingesetzten Zauber um 25%. 'Konvokation der Geister' hat eine erhöhte Chance, einen außergewöhnlichen Zauber oder eine außergewöhnliche Fähigkeit einzusetzen." }
entries[393993] = { ["name"] = "Gewebter Chronostoff", ["text"] = "Ca. 9 Procs pro Minute\nEure Zauber und Fähigkeiten haben eine Chance, Momente zu speichern. Bei 20 Stapeln wird die gespeicherte Zeit freigesetzt, und Ihr erhaltet einen Schub an Tempo." }
entries[393994] = { ["name"] = "Müde Sande", ["text"] = "Sofort\nVerlangsamt Euren Körper, indem er das Gewicht der Zeit selbst trägt.\n\nBewegungsgeschwindigkeit 1 Min. lang um 50% verringert." }
