entries[394036] = { ["name"] = "Gezackter Knochenstachel", ["text"] = "100 Meter Reichweite\nSofort\nBenötigt Einhändige Nahkampfwaffe\nSteckt einen Knochenstachel in das Ziel, der (174.24% der Angriffskraft) körperlichen Schaden sowie alle 3 Sek. (17.424% der Angriffskraft) Blutungsschaden verursacht, bis das Ziel stirbt oder den Kampf verlässt.\n\nWenn das Ziel stirbt, wird 1 Aufladung erstattet.\n\nGewährt 1 Combopunkt plus 1 weiteren pro aktivem Knochenstachel." }
