entries[394322] = { ["name"] = "Expeditionssprengladungen", ["text"] = "40 Meter Reichweite\nSofort 5 min Abklingzeit\nIn der Nähe von versperrten Höhlen platzieren, um den Eingang freizusprengen.\n\nAchtung: Bei der Verwendung von Sprengladungen ist Vorsicht geboten!\n\nFügt Gegnern im Umkreis von 8 22500 Feuerschaden zu. Achtung: Sprengladungen verletzen auch verbündete Ziele im Explosionsbereich." }
entries[394323] = { ["name"] = "Abräumladung", ["text"] = "100 Meter Reichweite\nSofort\nIn der Nähe von versperrten Höhlen platzieren, um den Eingang freizusprengen.\n\nAchtung: Bei der Verwendung von Sprengladungen ist Vorsicht geboten!\n\nFügt Gegnern im Umkreis von 8 22500 Feuerschaden zu. Achtung: Sprengladungen verletzen auch verbündete Ziele im Explosionsbereich." }
entries[394324] = { ["name"] = "Tödliches Gift", ["text"] = "100 Meter Reichweite\nSofort\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften. Das Gift verursacht im Verlauf von 12 Sek. [(11.374% der Angriffskraft) * 12 / 2] Naturschaden. Weitere Anwendungen auf das Ziel während der Effektdauer verursachen sofort (8.14% der Angriffskraft) Naturschaden." }
entries[394325] = { ["name"] = "Tödliches Gift", ["text"] = "100 Meter Reichweite\nSofort\nWenn Eure Waffen vergiftet sind, besteht eine Chance, dass Ihr Zielen, die bereits mit Eurem tödlichen Gift vergiftet sind, (8.14% der Angriffskraft) Naturschaden zufügt." }
entries[394326] = { ["name"] = "Sofort wirkendes Gift", ["text"] = "100 Meter Reichweite\nSofort\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Angriff besteht eine Chance von 30%, den Gegner zu vergiften, was sofort (7.4% der Angriffskraft) Naturschaden verursacht." }
entries[394327] = { ["name"] = "Wundgift", ["text"] = "100 Meter Reichweite\nSofort\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Angriff besteht eine Chance von 30%, den Gegner zu vergiften, was sofort (4.07% der Angriffskraft) Naturschaden verursacht und 12 Sek. lang sämtliche erhaltene Heilung um 8% verringert. Dieser Effekt ist bis zu 3-mal stapelbar." }
entries[394328] = { ["name"] = "Verstärkendes Gift", ["text"] = "100 Meter Reichweite\nSofort\nÜberzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Angriff besteht eine Chance von 30%, den Gegner zu vergiften, was ihm (8.14% der Angriffskraft) Naturschaden zufügt und ihn für 12 Sek. mit 'Verstärkendes Gift' belegt. 'Vergiften' kann 10 Stapel 'Verstärkendes Gift' verbrauchen, um 35% mehr Schaden zu verursachen. Maximal 20 Stapel." }
entries[394329] = { ["name"] = "Titanische Wut", ["text"] = "'Odyns Zorn' versetzt Euch in den Wutzustand, verursacht 10% mehr Schaden und gewährt Euch 2 Stapel von 'Wirbelwind'." }
entries[394331] = { ["name"] = "Todesmal", ["text"] = "Sofort\nSchneidet einem Gegner ein Todesmal ein, das ihm (320% der Angriffskraft) Blutungsschaden im Verlauf von 16 Sek. zufügt. Solange das Mal besteht, werden 'Erdrosseln', 'Blutung' und Eure angewendeten tödlichen Gifte bei diesem Ziel dupliziert, was 100% des normalen Schadens verursacht." }
