entries[394443] = { ["name"] = "Monolithfaust", ["text"] = "20 Meter Reichweite\nWirken in 3.75 sek.\nDer Elementar reißt eine massive Steinplatte aus dem Boden, zerschmettert das aktuelle Ziel und verursacht 15 Naturschaden innerhalb von 5 Metern.\n\nDie Steinplatte zerspringt dabei und entfesselt einen ' Monolithtrümmer ', der Spielercharakteren innerhalb von 2.5 Metern um jeden Einschlag 20 Naturschaden zufügt." }
entries[394446] = { ["name"] = "Monolithtrümmer", ["text"] = "Unbegrenzte Reichweite\nSofort\nDer Elementar markiert sein Ziel als Jagdziel für tektonische Stacheln, die 4 Sek. lang alle 0.8 Sek. unter dem Ziel ausbrechen und innerhalb von 3 Metern 40 Naturschaden verursachen." }
entries[394447] = { ["name"] = "Gespinst", ["text"] = "30 Meter Reichweite\nWirken in 2 sek.\nSchleudert Netze auf einen Gegner, die ihm 5 körperlichen Schaden zufügen und das Ziel für 2 Sek. bewegungsunfähig machen." }
