entries[394454] = { ["name"] = "Widerhallende Freiheit", ["text"] = "100 Meter Reichweite\nSofort\nDer 'Segen der Freiheit' erhöht die Bewegungsgeschwindigkeit des Ziels um 30%. [ Segen des Zauberschutzes : 'Segen des Zauberschutzes' / 'Segen des Schutzes'] und 'Segen der Aufopferung' verringern den erlittenen Schaden des Ziels um 15%. Diese Effekte halten noch 8 Sek. lang an, nachdem der Segen abgelaufen ist." }
