entries[394564] = { ["name"] = "Teufelsrausch", ["text"] = "20 Meter Reichweite\nWirken in 1 sek. 7 sek. Abklingzeit\nStürmt vorwärts und fügt einem Gegner 10 Chaosschaden zu." }
entries[394565] = { ["name"] = "Kritisches Wachstum", ["text"] = "Sofort\nKritische Heilungen mit 'Erblühen' erhöhen die Heilung Eures nächsten Einsatzes von 'Wildwuchs' um 5%. Bis zu 5-mal stapelbar. Kritische Heilungen mit 'Blühendes Leben' verringern die Abklingzeit von 'Schnelligkeit der Natur' um 2 Sek." }
entries[394566] = { ["name"] = "Arkanschlag", ["text"] = "100 Meter Reichweite\nSofort 1 sek. Abklingzeit\nFeuert ein Geschoss ab, das dem ersten getroffenen Gegner moderaten Schaden zufügt." }
entries[394567] = { ["name"] = "Augenstrahl", ["text"] = "Unbegrenzte Reichweite\nWirken in 1 sek. 15 sek. Abklingzeit\nVerursacht 2 Sek. lang alle 0.2 Sek. 5 Chaosschaden." }
entries[394568] = { ["name"] = "Augenstrahl", ["text"] = "Sofort\nVerursacht 2 Sek. lang alle 0.2 Sek. 5 Chaosschaden." }
entries[394569] = { ["name"] = "Arkanschlag", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt allen Gegnern in einem Bereich Arkanschaden zu." }
entries[394570] = { ["name"] = "Energisches Lebensblut", ["text"] = "Sofort\nWenn Ihr 10 Aufladungen von 'Knochenschild' verbraucht, erhaltet Ihr 10 Sek. lang 10% Schaden und Tempo." }
entries[394571] = { ["name"] = "Quellendes Lebensblut", ["text"] = "Sofort\nWenn Ihr 10 Aufladungen von 'Knochenschild' verbraucht, erhaltet Ihr 10 Sek. lang 10% Schaden und Tempo." }
entries[394572] = { ["name"] = "Sturmgeladen", ["text"] = "Sofort\nSpielercharaktere werden mit einer positiven oder einer negativen Aufladung markiert. Spielercharaktere, die sich innerhalb von 8 Metern zu anderen Spielercharakteren mit der gleichen Aufladung befinden, erhalten ' Konzentrierte Aufladung ', während Spielercharaktere, die sich innerhalb von 8 Metern zu einem Spielercharakter mit der gegensätzlichen Aufladung befinden, mit ' Zerstreute Aufladung ' belegt werden." }
entries[394573] = { ["name"] = "Frostiger Furor", ["text"] = "Wirken in 2 sek.\nFrostrachen gerät in eine eisige Raserei, die sein Angriffstempo um 40% erhöht und ihn Spielercharakteren innerhalb von 20 Metern 20 Sek. lang alle 2 Sek. 2 Frostschaden zufügen lässt." }
entries[394574] = { ["name"] = "Positive Aufladung", ["text"] = "Unbegrenzte Reichweite\nSofort\nRaszageth markiert Spielercharaktere mit einer positiven oder einer negativen Aufladung. Spielercharaktere innerhalb von 5 Metern von Verbündeten mit der gleichen Aufladung erhalten ' Konzentrierte Aufladung '. Spielercharaktere innerhalb von 5 Metern von Verbündeten mit der gegensätzlichen Aufladung werden mit ' Zerstreute Aufladung ' belegt." }
entries[394575] = { ["name"] = "Negative Aufladung", ["text"] = "Unbegrenzte Reichweite\nSofort\nRaszageth markiert Spielercharaktere mit einer positiven oder einer negativen Aufladung. Spielercharaktere innerhalb von 5 Metern von Verbündeten mit der gleichen Aufladung erhalten ' Konzentrierte Aufladung '. Spielercharaktere innerhalb von 5 Metern von Verbündeten mit der gegensätzlichen Aufladung werden mit ' Zerstreute Aufladung ' belegt." }
entries[394576] = { ["name"] = "Positive Aufladung", ["text"] = "Unbegrenzte Reichweite\nSofort\nRaszageth markiert Spielercharaktere mit einer positiven oder einer negativen Aufladung. Spielercharaktere innerhalb von 5 Metern von Verbündeten mit der gleichen Aufladung erhalten ' Konzentrierte Aufladung '. Spielercharaktere innerhalb von 5 Metern von Verbündeten mit der gegensätzlichen Aufladung werden mit ' Zerstreute Aufladung ' belegt." }
