entries[394579] = { ["name"] = "Negative Aufladung", ["text"] = "Unbegrenzte Reichweite\nSofort\nGewährt Spielercharakteren mit der gleichen Aufladung ' Konzentrierte Aufladung '.\n\nBelegt Spielercharaktere mit der gegensätzlichen Aufladung mit ' Zerstreute Aufladung '." }
