entries[394582] = { ["name"] = "Konzentrierte Aufladung", ["text"] = "Unbegrenzte Reichweite\nSofort\nKontakt mit der gleichen Aufladung erhöht den verursachten Schaden um 200% und die hervorgerufene Heilung und Absorption um 200%." }
entries[394583] = { ["name"] = "Zerstreute Aufladung", ["text"] = "Unbegrenzte Reichweite\nSofort\nKontakt mit der gegensätzlichen Aufladung löst eine Explosion aus, die Spielercharakteren innerhalb von 5 Metern 529971 Naturschaden zufügt. Verursacht zusätzlich alle 1 Sek. 17666 Naturschaden." }
entries[394584] = { ["name"] = "Umkehrung", ["text"] = "Unbegrenzte Reichweite\nSofort\nRaszageth kehrt die Aufladung mehrerer Spielercharaktere um, was ihnen 3 Sek. lang ' Konzentrierte Aufladung ' gewährt und anschließend ihre Polarität zur gegensätzlichen Aufladung wechselt." }
